        const slot_end = @as(u32, self.base) + 36;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return false;
        const word = zbuf.readU16(self.buf, @as(usize, self.base + 34)) catch 0;
        return ((word >> 0) & 1) == 1;
