    pub fn term(self: Self) u64 {
        const slot_end = @as(u32, self.base) + 10;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU64(self.buf, @as(usize, self.base + 2)) catch 0;
    }

