        const slot_end = @as(u32, self.base) + 4;
        const header_end = @as(u32, self.base) + self.size_bytes;
        if (slot_end > header_end) return 0;
        return zbuf.readU16(self.buf, @as(usize, self.base + 2)) catch 0;
    }

