        alloc.free(self.data);
        self.data = &.{};
        if (self.conf_state) |*_bf| _bf.deinit(alloc);
        self.conf_state = null;
    }

    pub fn destroy(self: *SnapshotStruct, alloc: std.mem.Allocator) void {
        self.deinit(alloc);
