        }
        return s;
    }

    pub fn clone(self: SnapshotStruct, alloc: std.mem.Allocator) Error!*SnapshotStruct {
        const ptr = try alloc.create(SnapshotStruct);
        errdefer alloc.destroy(ptr);
        ptr.* = try self.cloneValue(alloc);
